/**
 * Random-state 3×3×3 scrambles from cubing.js (`randomScrambleForEvent('333')`).
 *
 * The scramble is generated by cubing.js in its own web worker: it picks a
 * uniformly random legal state and returns a short algorithm that produces it.
 * The heavy module is loaded lazily, the first time a scramble is requested or
 * when the app pre-warms it during idle time.
 */
import type { KPuzzle } from 'cubing/kpuzzle';
import { isPatternSolved } from '../puzzle/kpattern';
import { formatAlg, parseAlg } from '../puzzle/notation';
import type { Move } from '../puzzle/notation';

export interface GeneratedScramble {
  /** Normalised WCA notation, exactly the moves that will be applied. */
  readonly text: string;
  readonly moves: readonly Move[];
}

export class ScrambleError extends Error {
  constructor(message: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = 'ScrambleError';
  }
}

/** Source of raw scramble text; injectable for tests. */
export type ScrambleSource = () => Promise<string>;

let scrambleModule: Promise<typeof import('cubing/scramble')> | null = null;

function loadScrambleModule(): Promise<typeof import('cubing/scramble')> {
  scrambleModule ??= Promise.all([import('cubing/scramble'), import('cubing/search')])
    .then(([scramble, search]) => {
      search.setSearchDebug({ logPerf: false });
      return scramble;
    })
    .catch((error: unknown) => {
      scrambleModule = null;
      throw error;
    });
  return scrambleModule;
}

export const cubingScrambleSource: ScrambleSource = async () => {
  const { randomScrambleForEvent } = await loadScrambleModule();
  const alg = await randomScrambleForEvent('333');
  return alg.toString();
};

/**
 * Produces a validated scramble: parseable outer-face notation whose result is
 * not already solved (astronomically unlikely, but checked and retried).
 */
export async function generateScramble(
  kpuzzle: KPuzzle,
  source: ScrambleSource = cubingScrambleSource,
  attempts = 3,
): Promise<GeneratedScramble> {
  let lastError: unknown = null;
  for (let attempt = 0; attempt < attempts; attempt++) {
    try {
      const raw = await source();
      const moves = parseAlg(raw);
      if (moves.length === 0) continue;
      const pattern = kpuzzle.defaultPattern().applyAlg(formatAlg(moves));
      if (isPatternSolved(pattern)) continue;
      return { text: formatAlg(moves), moves };
    } catch (error) {
      lastError = error;
    }
  }
  throw new ScrambleError('Could not generate a scramble.', { cause: lastError });
}

/** Starts the scramble worker in the background so the first scramble is fast. */
export async function prewarmScrambler(): Promise<void> {
  await cubingScrambleSource();
}
